// Custom Worker entry: the agent's JSON routes and cron tick, then the OpenNext handler for the Next.js pages.
// @ts-ignore .open-next/worker.js is generated by `opennextjs-cloudflare build`
import { default as handler } from "./.open-next/worker.js";
import { handleApi } from "./worker/api";
import { runCron, type CronEnv } from "./worker/cron";

type Ctx = { waitUntil(p: Promise<unknown>): void };

export default {
  async fetch(req: Request, env: CronEnv, ctx: Ctx) {
    return (await handleApi(req, env.UPKEEP_KV ?? null)) ?? handler.fetch(req, env, ctx);
  },
  async scheduled(_controller: unknown, env: CronEnv, ctx: Ctx) {
    ctx.waitUntil(runCron(env));
  },
};
